def _day_norm_hours(dk, schedule_mode, holidays):
    try:
        wd = datetime.strptime(dk, '%Y-%m-%d').weekday()
    except Exception:
        return 8.0
    if holidays and dk in holidays:
        return 0.0
    norms = EXTENDED_NORMS if schedule_mode == 'extended' else LEGACY_NORMS
    return norms.get(wd, 0.0)

