def _employee_capacity_hours(e, d1_iso, d2_iso, holidays, schedule_mode='legacy'):
    """PATCH 1.0.17: ёмкость в часах с учётом режима графика."""
    hired = (e.get('hired_date') or '').strip()
    fired = (e.get('fired_date') or '').strip() if e.get('fired') else ''
    start_iso = d1_iso
    end_iso = d2_iso
    if hired and hired > start_iso:
        start_iso = hired
    if fired and fired < end_iso:
        end_iso = fired
    if start_iso > end_iso:
        return 0.0
    absence_dates = set()
    for v in (e.get('vacations') or []):
        vt = v.get('type') or 'vacation'
        if vt == 'remote':
            continue
        vf = v.get('from') or ''
        vto = v.get('to') or ''
        if not vf or not vto:
            continue
        s = max(vf, start_iso)
        en = min(vto, end_iso)
        if s > en:
            continue
        try:
            cur = datetime.strptime(s, '%Y-%m-%d').date()
            end = datetime.strptime(en, '%Y-%m-%d').date()
            while cur <= end:
                iso = cur.strftime('%Y-%m-%d')
                if cur.weekday() < 5 and iso not in holidays:
                    absence_dates.add(iso)
                cur += timedelta(days=1)
        except Exception:
            pass
    try:
        start = datetime.strptime(start_iso, '%Y-%m-%d').date()
        end = datetime.strptime(end_iso, '%Y-%m-%d').date()
    except Exception:
        return 0.0
    total = 0.0
    cur = start
    while cur <= end:
        iso = cur.strftime('%Y-%m-%d')
        wd = cur.weekday()
        if wd < 5 and iso not in holidays and iso not in absence_dates:
            if schedule_mode == 'extended':
                total += 7.75 if wd == 4 else 8.25
            else:
                total += 8.0
        cur += timedelta(days=1)
    return total


