/* PATCH 1.0.17 — UI: график работы */
(function(){
'use strict';
if (window.__trkWorkScheduleUI) return;
window.__trkWorkScheduleUI = true;

function _csrf(){ return window.REESTR_CSRF || ''; }
function _notify(msg, kind){
    if (typeof window.__settingsNotify === 'function') { try { window.__settingsNotify(msg, kind); return; } catch(e){} }
}

function _load(){
    fetch('/api/settings/work_schedule', {credentials: 'same-origin'})
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(d){
            if (!d || !d.success) return;
            var leg = document.getElementById('wsLegacy');
            var ext = document.getElementById('wsExtended');
            if (d.mode === 'extended') { if (ext) ext.checked = true; }
            else { if (leg) leg.checked = true; }
        }).catch(function(){});
}

function _save(mode){
    var h = {'Content-Type': 'application/json'};
    if (_csrf()) h['X-CSRF-Token'] = _csrf();
    fetch('/api/settings/work_schedule', {
        method: 'POST', credentials: 'same-origin', headers: h,
        body: JSON.stringify({mode: mode})
    }).then(function(r){ return r.json(); }).then(function(d){
        if (d && d.success) {
            _notify('✅ График сохранён. Перезагрузите страницу для обновления норм.');
        } else {
            _notify('❌ ' + ((d && d.error) || 'Ошибка'), 'error');
        }
    }).catch(function(e){ _notify('❌ ' + (e.message || 'Ошибка'), 'error'); });
}

function _wire(){
    ['wsLegacy', 'wsExtended'].forEach(function(id){
        var el = document.getElementById(id);
        if (el && !el._wsWired) {
            el._wsWired = true;
            el.addEventListener('change', function(){ if (this.checked) _save(this.value); });
        }
    });
}

document.addEventListener('click', function(e){
    if (e.target && e.target.closest && e.target.closest('.settings-tab[data-tab="db"]')) {
        setTimeout(function(){ _wire(); _load(); }, 150);
    }
});

function boot(){ setTimeout(function(){ _wire(); _load(); }, 300); }
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
